import React from "react";
import { useNavigate } from "react-router-dom";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT SIDE (UNCHANGED) */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Builder • UI Thinker
          </h2>

          <p className="desc">
            I design structured systems and build meaningful applications
            where logic, design, and performance work together.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>
            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT SIDE - RADAR DESIGN */}
        <div className="right">

          <div className="radar">

            {/* CENTER IMAGE */}
            <div className="center">
              <img
                src="/mnt/data/e89799cc-4014-412e-bb6d-b1e9406c0077.png"
                alt="avatar"
              />
              <p>Swetha A</p>
            </div>

            {/* RINGS */}
            <div className="ring ring1"></div>
            <div className="ring ring2"></div>
            <div className="ring ring3"></div>

            {/* LABELS ON CIRCLE (STATIC POSITIONS) */}

            <div className="label l1">Java</div>
            <div className="label l2">Data Analytics</div>
            <div className="label l3">Python</div>
            <div className="label l4">UI/UX Design</div>
            <div className="label l5">SQL</div>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 {
          font-size: 62px;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
          cursor: pointer;
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* =========================
           RADAR SYSTEM (RIGHT SIDE)
        ========================== */

        .radar {
          position: relative;
          width: 380px;
          height: 380px;
          margin: auto;
        }

        /* RINGS (STATIC - NO ANIMATION) */
        .ring {
          position: absolute;
          border-radius: 50%;
          border: 1px solid rgba(56,189,248,0.15);
        }

        .ring1 {
          width: 360px;
          height: 360px;
          top: 10px;
          left: 10px;
        }

        .ring2 {
          width: 260px;
          height: 260px;
          top: 60px;
          left: 60px;
        }

        .ring3 {
          width: 160px;
          height: 160px;
          top: 110px;
          left: 110px;
          border: 1px solid rgba(56,189,248,0.08);
        }

        /* CENTER IMAGE */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          text-align: center;
          z-index: 5;
        }

        .center img {
          width: 110px;
          height: 110px;
          border-radius: 50%;
          object-fit: cover;
          border: 2px solid rgba(56,189,248,0.5);
          box-shadow: 0 0 25px rgba(56,189,248,0.2);
        }

        .center p {
          font-size: 12px;
          color: #94a3b8;
          margin-top: 6px;
        }

        /* =========================
           LABELS ON CIRCLE (STATIC RADIAL POSITIONS)
        ========================== */

        .label {
          position: absolute;
          padding: 6px 12px;
          border-radius: 20px;

          font-size: 11px;
          color: #cbd5e1;

          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);

          backdrop-filter: blur(8px);
        }

        /* Around outer ring */
        .l1 { top: 0; left: 50%; transform: translateX(-50%); }
        .l2 { top: 25%; right: 0; }
        .l3 { bottom: 0; left: 50%; transform: translateX(-50%); }
        .l4 { top: 50%; left: 0; transform: translateY(-50%); }
        .l5 { bottom: 25%; right: 10%; }

        /* =========================
           RESPONSIVE
        ========================== */

        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          h1 {
            font-size: 42px;
          }

          .buttons {
            justify-content: center;
          }

          .radar {
            margin-top: 40px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
